import sys
from math import gcd

def main():
    data = sys.stdin.buffer.read().split()
    M, Q = int(data[0]), int(data[1])
    primes = []
    x = M
    p = 2
    while p * p <= x:
        if x % p == 0:
            e = 0
            while x % p == 0:
                x //= p
                e += 1
            primes.append(p)
        p += 1 if p == 2 else 2
    if x > 1:
        primes.append(x)
    def d(v):
        res = 1
        for q in primes:
            if v % q == 0:
                e = 0
                while v % q == 0:
                    v //= q
                    e += 1
                res *= e + 1
        return res
    dM = d(M)
    out = []
    for i in range(Q):
        t = int(data[2 + 2 * i])
        r = int(data[3 + 2 * i])
        if t == 1:
            out.append(d(gcd(M, r)))
        else:
            c = d(M // r) if M % r == 0 else 0
            out.append(c if t == 2 else dM - c)
    print('\n'.join(map(str, out)))

main()

